<?php require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('documents.manage'); $bid=current_branch_id(); $id=(int)($_GET['id']??0); $d=one('SELECT * FROM documents WHERE id=? AND branch_id=?',[$id,$bid]); if(!$d) {http_response_code(404); exit('File not found');} $path=dirname(__DIR__).'/'.$d['file_path']; if(!is_file($path)){http_response_code(404); exit('Stored file missing');} header('Content-Type: '.($d['mime_type']?:'application/octet-stream')); header('Content-Disposition: attachment; filename="'.basename($d['original_name']).'"'); readfile($path); exit; ?>